import numpy as np
from scipy import stats
from sklearn.metrics import roc_auc_score
from collections import defaultdict

MAX_DRIVERS = 5

def design(feats):
    # Find features with significant association (p < 0.05)
    sig_features = []
    for i, fid in enumerate(feats.ids):
        if feats.types[i] == 'clinical' or feats.types[i] == 'expression' or feats.types[i] == 'copy_number':
            t_stat, p_val = stats.ttest_ind(feats.x[feats.y==1, i], feats.x[feats.y==0, i])
            if p_val < 0.05:
                sig_features.append((fid, t_stat, p_val))

    # Sort by absolute t-statistic
    sig_features.sort(key=lambda x: abs(x[1]), reverse=True)

    # Check for correlated pairs with |r| >= 0.6
    correlated_pairs = []
    for i in range(len(feats.ids)):
        for j in range(i+1, len(feats.ids)):
            r, _ = stats.pearsonr(feats.x[:,i], feats.x[:,j])
            if abs(r) >= 0.6:
                correlated_pairs.append((feats.ids[i], feats.ids[j]))

    # Look for product terms among top features
    drivers = []
    columns = []
    products = []
    loadings = {}

    # Try to find a strong driver feature
    if len(sig_features) > 0:
        # Take top 3 features
        top_features = [f[0] for f in sig_features[:3]]

        # Check for potential interaction terms
        for i in range(len(top_features)):
            for j in range(i+1, len(top_features)):
                fid1, fid2 = top_features[i], top_features[j]
                # Add product term
                products.append((fid1, fid2))

        # Use top features as drivers if they're not too correlated
        drivers = top_features[:MAX_DRIVERS]

        # Include all significant features in model
        columns = [f[0] for f in sig_features[:10]]  # Top 10 features

        # Add some product terms
        if len(top_features) >= 2:
            products = [(top_features[0], top_features[1])]

    # If no clear mechanism, return empty drivers
    if len(drivers) == 0:
        return Design(drivers=(), columns=(), products=(), loadings={})

    return Design(drivers=tuple(drivers), columns=tuple(columns), products=tuple(products), loadings=loadings)

